const VEL_MAX  = 100;  // velocidad con el gatillo a fondo (0 a 100)
const ARRANQUE = 15;   // mínimo con el que el motor empieza a girar
const PASO     = 5;    // cuánto sube o baja en cada paso
const TIEMPO   = 100;  // milisegundos entre pasos

if (msg.topic === "pedal") context.set("pedal", msg.payload);
else if (msg.topic === "boton") context.set("boton", msg.payload === 1);
else if (msg.topic === "obstaculo") context.set("obstaculo", msg.payload);
else throw new Error(`Topic desconocido: ${msg.topic}`);

const pedal = context.get("pedal") || 0;
const boton = context.get("boton") || false;
const obstaculo = context.get("obstaculo") || false;

// El sensor bloquea el avance, pero deja retroceder para salir
const frenar = boton || (obstaculo && pedal >= 0);

if (frenar) {
    if (context.get("frenando")) return null;
    clearInterval(context.get("timer"));
    context.set("timer", null);
    context.set("frenando", true);
    context.set("vel", 0);
    context.set("dir", "parar");
    return [{ payload: 1 }, { payload: 1 }, { payload: 100 }];
}

if (context.get("frenando")) {
    context.set("frenando", false);
    node.send([{ payload: 0 }, { payload: 0 }, { payload: 0 }]);
}

context.set("destino", pedal > 0 ? "adelante" : pedal < 0 ? "atras" : "parar");
context.set("velDestino", pedal === 0
    ? 0
    : Math.round(ARRANQUE + Math.abs(pedal) * (VEL_MAX - ARRANQUE)));

// Si la rampa ya está corriendo, va a tomar el nuevo destino sola
if (context.get("timer")) return null;

const pines = (d) => d === "adelante" ? [1, 0]
                   : d === "atras"    ? [0, 1]
                   :                    [0, 0];

const timer = setInterval(() => {
    const destino = context.get("destino");
    const velDestino = context.get("velDestino");
    let actual = context.get("vel") || 0;
    let dir = context.get("dir") || "parar";

    if (actual === 0 && destino !== dir) {
        dir = destino;
        const [a, b] = pines(dir);
        node.send([{ payload: a }, { payload: b }, null]);
        context.set("dir", dir);
    }

    const objetivo = destino === dir ? velDestino : 0;

    if (actual < objetivo) {
        actual = Math.max(Math.min(actual + PASO, objetivo), ARRANQUE);
    } else if (actual > objetivo) {
        actual = Math.max(actual - PASO, objetivo);
        if (actual < ARRANQUE) actual = objetivo;
    }
    context.set("vel", Math.min(actual, 75));
    node.send([null, null, { payload: actual }]);

    if (actual === objetivo && destino === dir) {
        clearInterval(timer);
        context.set("timer", null);
    }
}, TIEMPO);

context.set("timer", timer);
return null;

finalize:
clearInterval(context.get("timer"));
context.set("timer", null);
context.set("vel", 0);
context.set("dir", "parar");
context.set("frenando", false);

