const UMBRAL = 0.1;       // evita que un roce del gatillo mueva el motor
const ZONA_MUERTA = 0.1;  // ignora el ruido del stick

const { axes, buttons } = msg.payload;
const l2 = (axes[2] + 1) / 2;
const r2 = (axes[5] + 1) / 2;

const pedal = r2 >= l2 ? r2 : -l2;
const acel = Math.abs(pedal) < UMBRAL ? 0 : Math.round(pedal * 20) / 20;

const x = Math.abs(axes[0]) < ZONA_MUERTA ? 0 : Math.round(axes[0] * 10) / 10;

return [
    [
        { topic: "pedal", payload: acel },
        { topic: "boton", payload: buttons[3] },  // cuadrado
    ],
    { payload: x },
];

const ESPERA_MS = 500;  // tiempo para que el servo llegue al centro
const x = msg.payload;

clearTimeout(context.get("apagado"));

if (x === 0) {
    const apagado = setTimeout(() => node.send({ payload: 0 }), ESPERA_MS);
    context.set("apagado", apagado);
}

// izquierda = 5, centro = 7, derecha = 10
msg.payload = x < 0 ? 7 + x * 2 : 7 + x * 3;
return msg;

finalize:
clearTimeout(context.get("apagado"));
// Code added here will be run when the
// node is being stopped or re-deployed.

