const FRENO_CM = 50;
const LIBRE_CM = 55;  // margen para que no alterne al rondar los 15 cm
const SIN_LECTURA_MS = 2000;  // si el sensor deja de responder, no dejar el auto trabado

const cm = Number(msg.payload);
let obstaculo = context.get("obstaculo") || false;

if (cm < FRENO_CM) obstaculo = true;
else if (cm > LIBRE_CM) obstaculo = false;

context.set("obstaculo", obstaculo);
context.set("cm", cm);
node.status({ fill: obstaculo ? "red" : "green", shape: "dot", text: `${cm} cm` });
// El driver del sensor solo informa cuando la distancia cambia y no avisa
// si deja de responder: sin lecturas nuevas, el obstáculo se libera solo
clearTimeout(context.get("vigia"));
if (obstaculo) {
    context.set("vigia", setTimeout(() => {
        context.set("obstaculo", false);
        node.status({ fill: "yellow", shape: "ring", text: `sin lecturas desde ${cm} cm, libero` });
        node.send({ topic: "obstaculo", payload: false });
    }, SIN_LECTURA_MS));
}

return { topic: "obstaculo", payload: obstaculo };

const CANCION = "/home/pi/tonos/alarma.txt";

// Fin de la reproducción (salida de código de retorno del exec)
if (typeof msg.payload === "object" && "code" in msg.payload) {
    context.set("sonando", false);
    return null;
}

const { buttons } = msg.payload;
const x = buttons[0] === 1;         // X (cruz)
const cuadrado = buttons[3] === 1;  // cuadrado (además frena el motor)

// Solo cuenta al apretar, no mientras se mantiene
const xApretado = x && !context.get("x");
const cuadradoApretado = cuadrado && !context.get("cuadrado");
context.set("x", x);
context.set("cuadrado", cuadrado);

const sonando = context.get("sonando");
const parar = { kill: "SIGTERM", payload: "" };

if (cuadradoApretado && sonando) return parar;
if (!xApretado) return null;
if (sonando) return parar;  // X mientras suena también la corta

context.set("sonando", true);
return { payload: CANCION };
